import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Chat } from "@google/genai";
import { IconMessageCircle, IconX, IconSend, IconTrash, IconWhatsApp } from './Icons';
import { ChatMessage } from '../types';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Olá! Sou o assistente virtual da TaxOptimize. Como posso ajudar com suas dúvidas sobre impostos ou serviços hoje?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<Chat | null>(null);

  // Initialize Chat Session Function
  const initChat = () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      chatSessionRef.current = ai.chats.create({
          model: 'gemini-2.5-flash',
          config: {
              systemInstruction: `Você é um assistente virtual útil e profissional de uma empresa de contabilidade chamada TaxOptimize (semelhante à Conteles).
              Seu objetivo é responder perguntas básicas sobre contabilidade, abertura de empresas, impostos (Simples Nacional, Lucro Presumido) e BPO Financeiro.
              Responda de forma sucinta, amigável e em Português do Brasil.
              Sempre que a pergunta for muito complexa ou específica sobre um caso real, sugira que o usuário agende uma consulta com nossos especialistas humanos através do formulário de contato.
              Não dê conselhos legais definitivos, apenas orientações gerais.`,
          },
      });
    } catch (error) {
      console.error("Error initializing AI:", error);
    }
  };

  // Effect to initialize on open
  useEffect(() => {
    if (isOpen && !chatSessionRef.current) {
        initChat();
    }
  }, [isOpen]);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || !chatSessionRef.current) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await chatSessionRef.current.sendMessage({ message: userMsg });
      const text = response.text;

      setMessages(prev => [...prev, { role: 'model', text: text || "Desculpe, não consegui processar sua resposta agora." }]);
    } catch (error) {
      console.error("Error sending message:", error);
      setMessages(prev => [...prev, { role: 'model', text: "Ocorreu um erro ao conectar com o assistente. Por favor, tente novamente mais tarde." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClearChat = () => {
    setMessages([
        { role: 'model', text: 'Histórico limpo. Como posso ajudar você agora?' }
    ]);
    // Re-initialize to clear AI memory context
    initChat();
  };

  const handleWhatsApp = () => {
    const phoneNumber = '5544999999999'; // Substitua este número pelo número real fornecido
    const message = encodeURIComponent('Olá, gostaria de falar com um especialista da TaxOptimize.');
    window.open(`https://wa.me/${phoneNumber}?text=${message}`, '_blank');
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      <style>
        {`
          @keyframes slideUpFade {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
          }
          .animate-slide-up {
            animation: slideUpFade 0.3s ease-out forwards;
          }
        `}
      </style>

      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-40 p-4 bg-blue-600 text-white rounded-full shadow-2xl hover:bg-blue-700 transition-all transform hover:scale-110 ${isOpen ? 'hidden' : 'flex'}`}
        aria-label="Abrir chat"
      >
        <IconMessageCircle className="w-8 h-8" />
      </button>

      {/* Chat Interface */}
      {isOpen && (
        <div className="fixed bottom-0 right-0 sm:bottom-6 sm:right-6 w-full sm:w-96 h-[500px] bg-white sm:rounded-2xl shadow-2xl z-50 flex flex-col border border-gray-200 overflow-hidden font-sans">
          {/* Header */}
          <div className="bg-blue-900 p-4 text-white flex justify-between items-center shadow-md">
            <div className="flex items-center space-x-2">
              <div className={`w-2 h-2 rounded-full bg-green-400 ${isLoading ? 'animate-ping' : ''}`}></div>
              <h3 className="font-bold text-sm tracking-wide">TaxOptimize Assistente</h3>
            </div>
            <div className="flex items-center space-x-3">
                <button 
                    onClick={handleWhatsApp}
                    className="text-green-300 hover:text-green-400 transition-colors"
                    title="Falar no WhatsApp"
                >
                    <IconWhatsApp className="w-5 h-5" />
                </button>
                <button 
                    onClick={handleClearChat}
                    className="text-blue-200 hover:text-white transition-colors"
                    title="Limpar histórico"
                >
                    <IconTrash className="w-4 h-4" />
                </button>
                <div className="h-4 w-px bg-blue-700"></div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="text-blue-200 hover:text-white transition-colors"
                >
                <IconX className="w-5 h-5" />
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-1 p-4 overflow-y-auto bg-slate-50 space-y-4">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
                <div 
                  className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                    msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-white text-slate-700 border border-gray-100 rounded-bl-none'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex flex-col space-y-1 animate-slide-up">
                <div className="flex justify-start">
                    <div className="bg-white p-4 rounded-2xl rounded-bl-none shadow-sm border border-gray-100 flex space-x-1.5 items-center">
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce delay-150"></div>
                    <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce delay-300"></div>
                    </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-gray-100 relative">
            {isLoading && (
                 <div className="absolute -top-6 left-4 text-[10px] font-medium text-blue-500 animate-pulse bg-white/80 px-2 rounded-t-md">
                     TaxOptimize está digitando...
                 </div>
            )}
            <div className="flex items-center bg-slate-50 rounded-full px-4 py-2 border border-slate-200 focus-within:ring-2 focus-within:ring-blue-500 transition-all">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Digite sua dúvida..."
                className="flex-1 bg-transparent border-none outline-none text-sm text-slate-700 placeholder-slate-400"
                disabled={isLoading}
              />
              <button 
                onClick={handleSend}
                disabled={isLoading || !input.trim()}
                className={`ml-2 p-1.5 rounded-full transition-colors ${
                  !input.trim() ? 'text-gray-300' : 'text-blue-600 hover:bg-blue-100'
                }`}
              >
                <IconSend className="w-5 h-5" />
              </button>
            </div>
            <div className="text-center mt-2">
                <p className="text-[10px] text-gray-400">IA pode cometer erros. Consulte um especialista.</p>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

