import { IconChevronLeft, IconChevronRight } from './Icons';

// Utilizando SVGs da biblioteca Logoipsum para simular clientes reais com alta qualidade visual
const clients = [
  { name: 'Vortex', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-211.svg' },
  { name: 'Nexa', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-213.svg' },
  { name: 'Sphere', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-215.svg' },
