  { name: 'Echo', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-219.svg' },
  { name: 'Vertex', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-221.svg' },
  { name: 'Horizon', logo: 'https://raw.githubusercontent.com/sahilolic/logoipsum/master/logoipsum-223.svg' },
