export const Services: React.FC = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [itemsPerPage, setItemsPerPage] = useState(3);
  const [isPaused, setIsPaused] = useState(false);
  const [isTransitioning, setIsTransitioning] = useState(true);

  // Duplicamos a lista para criar o efeito de loop infinito
  // A lista será [0, 1, 2, 3, 0(clone), 1(clone), 2(clone), 3(clone)]
  const displayServices = [...services, ...services];

  // Responsive logic
  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 768) {
        setItemsPerPage(1);
      } else if (width < 1024) {
        setItemsPerPage(2);
      } else {
        setItemsPerPage(3);
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Lógica do Próximo Slide (Loop Infinito)
  const nextSlide = useCallback(() => {
    if (!isTransitioning) return;

    setCurrentIndex((prev) => {
      // Avança um slide
      return prev + 1;
    });
  }, [isTransitioning]);

  const prevSlide = () => {
    if (currentIndex === 0) return; // Simples block para evitar bug visual na demo, foco é o loop forward
    setCurrentIndex((prev) => prev - 1);
  };

  const goToSlide = (index: number) => {
    setCurrentIndex(index);
  };

  // Efeito de "Snap" (Pulo silencioso) para o loop infinito
  useEffect(() => {
    // Se chegarmos ao índice igual ao tamanho original da lista (ex: 4)
    // Isso significa que estamos vendo o primeiro item "clonado"
    if (currentIndex === services.length) {
      // Esperamos a transição visual terminar (700ms)
      const timeout = setTimeout(() => {
        setIsTransitioning(false); // Desliga a animação
        setCurrentIndex(0); // Pula instantaneamente para o índice 0 real
      }, 700);

      return () => clearTimeout(timeout);
    }
  }, [currentIndex]);

  // Religador da transição após o snap
  useEffect(() => {
    if (!isTransitioning) {
      // Força um pequeno delay para o React renderizar o estado sem transição
      // antes de ligar a transição novamente para o próximo movimento
      const timeout = setTimeout(() => {
        setIsTransitioning(true);
      }, 50);
      return () => clearTimeout(timeout);
    }
  }, [isTransitioning]);

  // Auto-play Logic (5 seconds)
  useEffect(() => {
    if (isPaused) return;

    const interval = setInterval(() => {
      nextSlide();
