import React, { useState } from 'react';
import { IconCheck, IconX } from './Icons';

interface ContactProps {
  onSuccess: () => void;
}

export const Contact: React.FC<ContactProps> = ({ onSuccess }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    company: '',
    revenue: '',   // Novo: Qualificação de Porte
    regime: '',    // Novo: Qualificação Técnica
    sector: '',    // Novo: Contexto de Mercado
    mainNeed: '',  // Novo: Dor do Cliente / Problema Tributário
    message: ''
  });

  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Regras de validação atualizadas para qualificação
  const validate = (name: string, value: string) => {
    switch (name) {
      case 'name':
        return value.trim().length >= 3;
      case 'email':
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      case 'phone':
        return value.replace(/\D/g, '').length >= 10;
      case 'message':
        return value.trim().length >= 10;
      // Novos campos de qualificação são obrigatórios para análise
      case 'revenue': 
      case 'regime': 
      case 'sector': 
      case 'mainNeed':
        return value !== ''; 
      case 'company':
        return true; 
      default:
        return true;
    }
  };

  const isFieldValid = (name: string) => validate(name, formData[name as keyof typeof formData]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const requiredFields = ['name', 'email', 'phone', 'message', 'revenue', 'regime', 'sector', 'mainNeed'];
    const hasErrors = requiredFields.some(field => !validate(field, formData[field as keyof typeof formData]));

    if (hasErrors) {
      const allTouched = requiredFields.reduce((acc, curr) => ({ ...acc, [curr]: true }), {});
      setTouched(prev => ({ ...prev, ...allTouched }));

      const firstError = requiredFields.find(field => !validate(field, formData[field as keyof typeof formData]));
      if (firstError) {
        const element = document.getElementById(firstError);
        element?.focus();
      }
      return;
    }

    setIsSubmitting(true);

    // =================================================================================
    // CONFIGURAÇÃO DE ENVIO VIA FORMSUBMIT (SEM BACKEND PHP)
    // =================================================================================
    // O FormSubmit lida com o envio de e-mail e resolve problemas de CORS automaticamente.
    // O e-mail de destino foi extraído da página de sucesso: shigueme@shirabe.com.br

    const DESTINATION_EMAIL = "shigueme@shirabe.com.br"; 
    const API_URL = `https://formsubmit.co/ajax/${DESTINATION_EMAIL}`;

    try {
      // Payload formatado para leitura fácil no e-mail
      const payload = {
        _subject: `Novo Lead: ${formData.name} - Shigueme Consultoria`,
        _template: "table", // Formata o e-mail como uma tabela bonita
        _captcha: "false",  // Desativa o captcha visual (opcional)

        // Dados do Lead
        "Nome Completo": formData.name,
        "Email": formData.email,
        "Telefone/WhatsApp": formData.phone,
        "Empresa": formData.company || 'Não informada',

        // Qualificação
        "Faturamento Estimado": formatRevenue(formData.revenue),
        "Regime Tributário": formatRegime(formData.regime),
        "Setor de Atuação": formatSector(formData.sector),
        "Necessidade Principal": formatNeed(formData.mainNeed),

        // Mensagem
        "Mensagem Detalhada": formData.message,
        "Data do Envio": new Date().toLocaleString('pt-BR')
      };

      const response = await fetch(API_URL, {
         method: 'POST',
         headers: { 
           'Content-Type': 'application/json',
           'Accept': 'application/json'
         },
         body: JSON.stringify(payload)
       });

       if (!response.ok) {
          throw new Error(`Erro no envio: ${response.status}`);
       }

      setFormData({ 
        name: '', email: '', phone: '', company: '', message: '',
        revenue: '', regime: '', sector: '', mainNeed: ''
      });
      setTouched({});
      onSuccess();

    } catch (error) {
      console.error("Erro ao enviar formulário:", error);
      alert("Houve uma falha técnica ao enviar seus dados. Por favor, tente novamente ou entre em contato pelo WhatsApp.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Helpers para formatar os valores do select para o e-mail ficar legível
  const formatRevenue = (val: string) => {
    const map: Record<string, string> = {
        'ate_50k': 'Até R$ 80 mil (MEI/Micro)',
        '50k_300k': 'R$ 80 mil a R$ 300 mil',
        '300k_1m': 'R$ 300 mil a R$ 1 Milhão',
        '1m_5m': 'R$ 1 Milhão a R$ 5 Milhões',
        'acima_5m': 'Acima de R$ 5 Milhões'
    };
    return map[val] || val;
  };

  const formatRegime = (val: string) => {
      const map: Record<string, string> = {
          'simples': 'Simples Nacional',
          'presumido': 'Lucro Presumido',
          'real': 'Lucro Real',
          'nao_sei': 'Não sei / Em abertura'
      };
      return map[val] || val;
  };

  const formatSector = (val: string) => {
      const map: Record<string, string> = {
          'industria': 'Indústria',
          'comercio': 'Comércio / Varejo',
          'servicos': 'Serviços',
          'agro': 'Agronegócio',
          'transporte': 'Transporte / Logística',
          'saude': 'Saúde',
          'outro': 'Outro'
      };
      return map[val] || val;
  };

  const formatNeed = (val: string) => {
      const map: Record<string, string> = {
          'reduzir_carga': 'Reduzir Impostos',
          'dividas': 'Regularização de Dívidas',
          'recuperacao_credito': 'Recuperação de Créditos',
          'reforma_tributaria': 'Reforma Tributária',
          'bpo': 'BPO Financeiro',
          'fiscalizacao': 'Fiscalização / Autuação',
          'abertura': 'Abertura de Empresa'
      };
      return map[val] || val;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setTouched({
      ...touched,
      [e.target.name]: true
    });
  };

  const getInputClasses = (fieldName: string) => {
    const baseClasses = "w-full rounded-lg border p-3 outline-none transition-all duration-200 pr-10 bg-white text-slate-900 appearance-none"; 
    const isTouched = touched[fieldName];
    const isValid = isFieldValid(fieldName);

    if (!isTouched && fieldName !== 'company') {
      return `${baseClasses} border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500`;
    }

    if (fieldName === 'company') {
       return `${baseClasses} border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500`;
    }

    return isValid
      ? `${baseClasses} border-green-500 bg-green-50 text-slate-900 focus:ring-2 focus:ring-green-500 focus:border-green-500`
      : `${baseClasses} border-red-500 bg-red-50 text-slate-900 focus:ring-2 focus:ring-red-500 focus:border-red-500`;
  };

  return (
    <div id="contact" className="bg-slate-900 py-24 text-white">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">

        <div className="text-center mb-12">
            <h2 className="text-blue-400 font-semibold tracking-wide uppercase text-sm mb-3">Diagnóstico Tributário</h2>
            <h3 className="text-3xl md:text-4xl font-bold mb-4">Solicite uma Análise Especializada</h3>
            <p className="text-slate-300 text-lg max-w-2xl mx-auto">
              Preencha os dados abaixo para que nossos analistas entendam o perfil do seu negócio e proponham as melhores soluções.
            </p>
        </div>

        <div className="bg-white rounded-2xl p-8 md:p-10 text-slate-800 shadow-2xl border border-slate-800/50">
            <h3 className="text-2xl font-bold mb-8 text-center text-slate-900">Perfil Empresarial & Contato</h3>
            <form onSubmit={handleSubmit} className="space-y-6" noValidate aria-label="Formulário de qualificação tributária">

              {/* BLOCO 1: Identificação Básica */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="relative">
                  <label htmlFor="name" className="block text-sm font-bold text-slate-700 mb-1">Nome do Responsável *</label>
                  <div className="relative">
                    <input
                        type="text"
                        name="name"
                        id="name"
                        required
                        value={formData.name}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        disabled={isSubmitting}
                        className={getInputClasses('name')}
                        placeholder="Nome completo"
                    />
                    {touched.name && (
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                            {isFieldValid('name') ? <IconCheck className="h-5 w-5 text-green-500" /> : <IconX className="h-5 w-5 text-red-500" />}
                        </div>
                    )}
                  </div>
                </div>
                <div>
                  <label htmlFor="company" className="block text-sm font-bold text-slate-700 mb-1">Nome da Empresa</label>
                  <input
                    type="text"
                    name="company"
                    id="company"
                    value={formData.company}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    disabled={isSubmitting}
                    className={getInputClasses('company')}
                    placeholder="Razão Social ou Nome Fantasia"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="relative">
                  <label htmlFor="email" className="block text-sm font-bold text-slate-700 mb-1">Email Corporativo *</label>
                  <div className="relative">
                    <input
                        type="email"
                        name="email"
                        id="email"
                        required
                        value={formData.email}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        disabled={isSubmitting}
                        className={getInputClasses('email')}
                        placeholder="voce@suaempresa.com.br"
                    />
                    {touched.email && (
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                            {isFieldValid('email') ? <IconCheck className="h-5 w-5 text-green-500" /> : <IconX className="h-5 w-5 text-red-500" />}
                        </div>
                    )}
                  </div>
                </div>
                <div className="relative">
                  <label htmlFor="phone" className="block text-sm font-bold text-slate-700 mb-1">WhatsApp / Telefone *</label>
                  <div className="relative">
                    <input
                        type="tel"
                        name="phone"
                        id="phone"
                        required
                        value={formData.phone}
                        onChange={handleChange}
                        onBlur={handleBlur}
                        disabled={isSubmitting}
                        className={getInputClasses('phone')}
                        placeholder="(DD) 99999-9999"
                    />
                    {touched.phone && (
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                            {isFieldValid('phone') ? <IconCheck className="h-5 w-5 text-green-500" /> : <IconX className="h-5 w-5 text-red-500" />}
                        </div>
                    )}
                  </div>
                </div>
              </div>

              {/* BLOCO 2: Qualificação Estratégica (Novos Campos) */}
              <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 mt-6">
                 <h4 className="text-blue-600 font-bold text-sm uppercase tracking-wider mb-4 border-b border-slate-200 pb-2">Dados para Análise Tributária</h4>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-5">
                    <div className="relative">
                        <label htmlFor="revenue" className="block text-sm font-semibold text-slate-700 mb-1">Faturamento Mensal Estimado *</label>
                        <div className="relative">
                            <select
                                name="revenue"
                                id="revenue"
                                required
                                value={formData.revenue}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                disabled={isSubmitting}
                                className={getInputClasses('revenue')}
                            >
                                <option value="">Selecione uma opção</option>
                                <option value="ate_50k">Até R$ 80 mil (MEI/Micro)</option>
                                <option value="50k_300k">R$ 80 mil a R$ 300 mil</option>
                                <option value="300k_1m">R$ 300 mil a R$ 1 Milhão</option>
                                <option value="1m_5m">R$ 1 Milhão a R$ 5 Milhões</option>
                                <option value="acima_5m">Acima de R$ 5 Milhões</option>
                            </select>
                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-500">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                    </div>

                    <div className="relative">
                        <label htmlFor="regime" className="block text-sm font-semibold text-slate-700 mb-1">Regime Tributário Atual *</label>
                        <div className="relative">
                            <select
                                name="regime"
                                id="regime"
                                required
                                value={formData.regime}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                disabled={isSubmitting}
                                className={getInputClasses('regime')}
                            >
                                <option value="">Selecione o regime</option>
                                <option value="simples">Simples Nacional</option>
                                <option value="presumido">Lucro Presumido</option>
                                <option value="real">Lucro Real</option>
                                <option value="nao_sei">Não sei / Em abertura</option>
                            </select>
                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-500">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                     <div className="relative">
                        <label htmlFor="sector" className="block text-sm font-semibold text-slate-700 mb-1">Setor de Atuação *</label>
                        <div className="relative">
                            <select
                                name="sector"
                                id="sector"
                                required
                                value={formData.sector}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                disabled={isSubmitting}
                                className={getInputClasses('sector')}
                            >
                                <option value="">Selecione o setor</option>
                                <option value="industria">Indústria (Transformação)</option>
                                <option value="comercio">Comércio / Varejo</option>
                                <option value="servicos">Prestação de Serviços</option>
                                <option value="agro">Agronegócio</option>
                                <option value="transporte">Transporte / Logística</option>
                                <option value="saude">Saúde / Clínicas</option>
                                <option value="outro">Outro</option>
                            </select>
                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-500">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                    </div>

                    <div className="relative">
                        <label htmlFor="mainNeed" className="block text-sm font-semibold text-slate-700 mb-1">Objetivo Principal *</label>
                        <div className="relative">
                            <select
                                name="mainNeed"
                                id="mainNeed"
                                required
                                value={formData.mainNeed}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                disabled={isSubmitting}
                                className={getInputClasses('mainNeed')}
                            >
                                <option value="">Qual o seu maior desafio?</option>
                                <option value="reduzir_carga">Reduzir Impostos (Planejamento)</option>
                                <option value="dividas">Regularização de Dívidas / Parcelamento</option>
                                <option value="recuperacao_credito">Recuperação de Créditos (Passado)</option>
                                <option value="reforma_tributaria">Adequação à Reforma Tributária</option>
                                <option value="bpo">Terceirização Financeira (BPO)</option>
                                <option value="fiscalizacao">Estou sob Fiscalização / Autuação</option>
                                <option value="abertura">Abertura de Empresa</option>
                            </select>
                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-500">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </div>
                        </div>
                    </div>
                 </div>
              </div>

              {/* BLOCO 3: Mensagem */}
              <div className="relative">
                <label htmlFor="message" className="block text-sm font-bold text-slate-700 mb-1">Detalhes do Problema *</label>
                <div className="relative">
                    <textarea
                    name="message"
                    id="message"
                    rows={4}
                    required
                    value={formData.message}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    disabled={isSubmitting}
                    className={getInputClasses('message')}
                    placeholder="Descreva brevemente sua situação atual ou o problema que deseja resolver..."
                    ></textarea>
                     {touched.message && (
                        <div className="absolute top-3 right-3 pointer-events-none">
                            {isFieldValid('message') ? <IconCheck className="h-5 w-5 text-green-500" /> : <IconX className="h-5 w-5 text-red-500" />}
                        </div>
                    )}
                </div>
                {touched.message && !isFieldValid('message') && (
                  <p id="error-message" className="text-xs text-red-500 mt-1">A mensagem deve ter pelo menos 10 caracteres.</p>
                )}
              </div>

              <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-blue-600 text-white font-bold py-4 px-6 rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-500/50 transition-all shadow-lg hover:shadow-blue-600/30 flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed text-lg"
              >
                {isSubmitting ? 'Enviando...' : 'Solicitar Diagnóstico Gratuito'}
              </button>
              <p className="text-xs text-center text-slate-500 mt-4">
                Seus dados comerciais são confidenciais e protegidos pela LGPD.
              </p>
            </form>
        </div>

      </div>
    </div>
  );
};

import React from 'react';

export interface ServiceItem {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  image: string;
}

export interface Testimonial {
  id: string;
  name: string;
  role: string;
  company: string;
  content: string;
  avatar: string;
}

// Tipos atualizados para o Chatbot
export interface ChatOption {
  label: string;
  value: string;
}

export interface ChatMessage {
  id: string;
  role: 'bot' | 'user';
  content: string | React.ReactNode;
  type?: 'text' | 'options' | 'input';
  options?: ChatOption[];
  inputType?: 'text' | 'email' | 'tel';
  isTyping?: boolean;
}

export interface UserData {
  name: string;
  email: string;
  phone: string;
  company: string;
  revenue: string;
  regime: string;
  sector: string;
  mainNeed: string;
  message: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { IconSend, IconMessageCircle, IconCheck, IconUser, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';

interface ContactProps {
  onSuccess?: () => void; // Mantido para compatibilidade, mas o fluxo é interno agora
}

// Define os passos do fluxo do chat
type ChatStep = 
  | 'INTRO' 
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const Contact: React.FC<ContactProps> = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [userData, setUserData] = useState<UserData>({
    name: '', email: '', phone: '', company: '', 
    revenue: '', regime: '', sector: '', mainNeed: '', message: ''
  });
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Scroll automático para a última mensagem
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping]);

  // Inicializa o chat
  useEffect(() => {
    addBotMessage("Olá! Sou o assistente virtual da Shigueme Consultoria. 🤖", 500);
    addBotMessage("Vou guiar seu diagnóstico tributário. Para começar, qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
  }, []);

  // Foca no input quando necessário
  useEffect(() => {
    if (!isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      // Pequeno delay para garantir que a UI renderizou
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isTyping, currentStep]);

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    // Máquina de estados do Chat
    switch (currentStep) {
      case 'NAME':
        if (value.length < 3) {
            addBotMessage("Por favor, digite um nome válido (mínimo 3 letras).", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: value }));
        addBotMessage(`Prazer, ${value.split(' ')[0]}! Qual é o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: value }));
        addBotMessage("Perfeito. Agora, qual é o seu melhor e-mail corporativo para contato?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(value)) {
            addBotMessage("Hmm, esse e-mail parece inválido. Tente novamente, por favor.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: value }));
        addBotMessage("Anotado. Qual é o seu WhatsApp ou telefone com DDD?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneClean = value.replace(/\D/g, '');
        if (phoneClean.length < 10) {
            addBotMessage("O número parece curto demais. Digite o DDD + Número.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: value }));

        // Pergunta com Opções - Faturamento
        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Para direcionar ao especialista certo, qual é o faturamento mensal estimado da empresa?", 600, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Entendido. Qual é o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recuperar Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar ou detalhes adicionais sobre o problema.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData); // Trigger submission
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Aguarde um momento, estou analisando seus dados e enviando para nossa equipe...", 500);

    try {
        // Substitua '/api/n8n-proxy.php' pelo caminho real do arquivo no servidor
        // Em ambiente de desenvolvimento local (Vite), isso pode precisar de ajuste de proxy no vite.config ou URL completa
        const response = await fetch('/api/n8n-proxy.php', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(data),
        });

        if (!response.ok) {
            throw new Error('Network error');
        }

        setCurrentStep('SUCCESS');
        addBotMessage("✅ Tudo certo! Recebemos sua solicitação com sucesso.", 1000);
        addBotMessage("Nossos especialistas em inteligência tributária analisarão seu perfil e entrarão em contato em breve pelo WhatsApp ou E-mail.", 2000);

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Tivemos um problema técnico ao conectar com o servidor.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão flutuante no canto da tela.", 2000);
    }
  };

  // Renderiza opções se existirem para a etapa atual e não estiver "digitando"
  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 animate-fade-in-up">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600/10 hover:bg-blue-600 hover:text-white text-blue-400 border border-blue-500/30 rounded-full px-4 py-2 text-sm font-medium transition-all"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div id="contact" className="bg-slate-900 py-24 text-white">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">

        <div className="text-center mb-10">
            <h2 className="text-blue-400 font-semibold tracking-wide uppercase text-sm mb-3">Diagnóstico Tributário via Chat</h2>
            <h3 className="text-3xl font-bold mb-4">Assistente Inteligente</h3>
            <p className="text-slate-400 text-sm">Converse conosco para agilizar seu atendimento.</p>
        </div>

        {/* Chat Container */}
        <div className="bg-slate-950 rounded-2xl shadow-2xl border border-slate-800 overflow-hidden flex flex-col h-[600px] md:h-[700px]">

            {/* Chat Header */}
            <div className="bg-slate-900 p-4 border-b border-slate-800 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="relative">
                        <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center">
                            <IconShield className="w-5 h-5 text-white" />
                        </div>
                        <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-slate-900"></div>
                    </div>
                    <div>
                        <h4 className="font-bold text-white text-sm">Shigueme AI</h4>
                        <p className="text-xs text-blue-400">Online agora</p>
                    </div>
                </div>
            </div>

            {/* Chat Area */}
            <div className="flex-grow p-4 md:p-6 overflow-y-auto space-y-4 scrollbar-hide bg-[url('https://grainy-gradients.vercel.app/noise.svg')] bg-opacity-5">

                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
                    >
                        <div className={`flex max-w-[85%] md:max-w-[70%] gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>

                            {/* Avatar */}
                            <div className="flex-shrink-0 mt-auto">
                                {msg.role === 'bot' ? (
                                    <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center border border-slate-700">
                                        <IconShield className="w-4 h-4 text-blue-400" />
                                    </div>
                                ) : (
                                    <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center border border-slate-600">
                                        <IconUser className="w-4 h-4 text-slate-300" />
                                    </div>
                                )}
                            </div>

                            {/* Bubble */}
                            <div className={`
                                p-3.5 rounded-2xl text-sm leading-relaxed shadow-md
                                ${msg.role === 'user' 
                                    ? 'bg-blue-600 text-white rounded-br-none' 
                                    : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'}
                            `}>
                                {msg.content}
                            </div>
                        </div>
                    </div>
                ))}

                {/* Typing Indicator */}
                {isTyping && (
                    <div className="flex justify-start w-full animate-fade-in">
                         <div className="flex items-end gap-3">
                            <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center border border-slate-700">
                                <IconShield className="w-4 h-4 text-blue-400" />
                            </div>
                            <div className="bg-slate-800 p-4 rounded-2xl rounded-bl-none border border-slate-700 flex items-center gap-1">
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce"></span>
                            </div>
                         </div>
                    </div>
                )}

                {/* Option Chips Area */}
                <div className="pl-11">
                    {renderOptions()}
                </div>

                <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 bg-slate-900 border-t border-slate-800">
                <form 
                    onSubmit={handleTextSubmit}
                    className={`flex items-center gap-3 bg-slate-950 border border-slate-700 rounded-xl px-4 py-3 transition-colors ${!isInputDisabled ? 'focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500/50' : 'opacity-50 cursor-not-allowed'}`}
                >
                    <IconMessageCircle className="text-slate-500 w-5 h-5" />
                    <input
                        ref={inputRef}
                        type={currentStep === 'PHONE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                        value={userInput}
                        onChange={(e) => setUserInput(e.target.value)}
                        placeholder={isInputDisabled ? (currentStep === 'SUCCESS' ? "Chat finalizado." : "Aguarde...") : "Digite sua resposta..."}
                        disabled={isInputDisabled}
                        className="flex-grow bg-transparent text-white placeholder-slate-500 outline-none text-sm"
                        autoComplete="off"
                    />
                    <button
                        type="submit"
                        disabled={isInputDisabled || !userInput.trim()}
                        className="p-2 bg-blue-600 rounded-lg text-white disabled:opacity-50 disabled:bg-slate-700 hover:bg-blue-500 transition-colors"
                    >
                        <IconSend className="w-4 h-4" />
                    </button>
                </form>
                <div className="text-center mt-2">
                    <p className="text-[10px] text-slate-600">
                        Shigueme Consultoria utiliza seus dados apenas para contato comercial.
                    </p>
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Clients } from './components/Clients';
import { Services } from './components/Services';
import { About } from './components/About';
import { Contact } from './components/Contact';
import { Footer } from './components/Footer';
import { AIAssistant } from './components/AIAssistant';
import { PrivacyPolicy } from './components/PrivacyPolicy';

// SuccessPage removida pois o chat lida com o estado de sucesso internamente
type Page = 'home' | 'privacy';

function App() {
  const [currentPage, setCurrentPage] = useState<Page>('home');

  const navigateToPrivacy = () => setCurrentPage('privacy');

  const navigateToHome = () => {
    setCurrentPage('home');
    window.scrollTo(0, 0); 
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900 scroll-smooth">

      {currentPage === 'home' && (
        <>
          <Navbar />
          <main className="flex-grow">
            <Hero />
            <Clients />
            <Services />
            <About />
            {/* O Chat (Contact) lida com o envio e mensagem de sucesso internamente */}
            <Contact />
          </main>
          <Footer onOpenPrivacy={navigateToPrivacy} />
          <AIAssistant />
        </>
      )}

      {currentPage === 'privacy' && (
        <PrivacyPolicy onBack={navigateToHome} />
      )}
    </div>
  );
}

export default App;

