const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_TYPE'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  // Estado para controlar a posição dinâmica com base no teclado (Mobile)
  const [keyboardOffset, setKeyboardOffset] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // EFEITO PARA DETECTAR O TECLADO MOBILE
  useEffect(() => {
    if (!window.visualViewport) return;

    const handleResize = () => {
      if (window.visualViewport) {
        // Calcula a diferença entre a altura da janela e o que está visível
        // Se a viewport visível for menor que a altura da janela, o teclado está aberto
        const offset = window.innerHeight - window.visualViewport.height;
        setKeyboardOffset(offset > 0 ? offset : 0);
      }
    };

    window.visualViewport.addEventListener('resize', handleResize);
    window.visualViewport.addEventListener('scroll', handleResize);

    return () => {
      window.visualViewport?.removeEventListener('resize', handleResize);
      window.visualViewport?.removeEventListener('scroll', handleResize);
    };
  }, []);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isOpen, isTyping]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);

    const docOptions: ChatOption[] = [
        { label: 'CPF (Pessoa Física)', value: 'CPF' },
        { label: 'CNPJ (Empresa)', value: 'CNPJ' }
    ];
    addBotMessage("Você gostaria de iniciar com CPF ou CNPJ?", 2500, () => setCurrentStep('DOC_TYPE'), docOptions);
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_TYPE':
        if (value === 'CPF' || value === 'CNPJ') {
            setUserData(prev => ({ ...prev, documentType: value }));
            addBotMessage(`Perfeito. Por favor, digite o número do ${value}.`, 600, () => setCurrentStep('DOC_VALUE'));
        } else {
            addBotMessage("Por favor, selecione uma das opções abaixo.", 500);
        }
        break;

      case 'DOC_VALUE':
        const isCpf = userData.documentType === 'CPF';
        const isValidDoc = isCpf ? validateCPF(value) : validateCNPJ(value);

        if (!isValidDoc) {
            addBotMessage(`${userData.documentType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        const formattedDoc = isCpf ? formatCPF(value) : formatCNPJ(value);
        setUserData(prev => ({ ...prev, documentValue: formattedDoc }));
        addBotMessage("Documento validado! ✅", 500);
        addBotMessage("Qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-50 flex flex-col items-end pointer-events-none"
      style={{ 
        bottom: `calc(${keyboardOffset}px + 1.5rem)`, 
        right: '1.5rem',
        left: keyboardOffset > 0 ? '1.5rem' : 'auto' // No mobile com teclado, centraliza ou expande
      }}
    >

      {/* Balão de Notificação */}
      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      {/* JANELA DO CHAT */}
      <div 
        className={`bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          keyboardOffset > 0 ? 'w-full h-[40vh]' : 'w-[320px] sm:w-[380px] h-[500px]'
        }`}
      >
         {/* Header */}
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         {/* Messages Area */}
         <div className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3">
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} />
         </div>

         {/* Input Area */}
         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      {/* FAB (Floating Action Button) */}
      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto ${
            isOpen ? 'bg-slate-700 rotate-90' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: keyboardOffset > 0 && isOpen ? 'none' : 'flex' }} // Esconde o botão quando o teclado está aberto no mobile para ganhar espaço
      >
        {isOpen ? (
            <IconX className="w-6 h-6 text-white" />
        ) : (
            <>
                <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
                <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
                {showNotification && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
                )}
            </>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

// CONFIGURAÇÃO DA URL DO N8N
const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_TYPE'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  const [keyboardOffset, setKeyboardOffset] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // EFEITO PARA DETECTAR O TECLADO MOBILE
  useEffect(() => {
    if (!window.visualViewport) return;

    const handleResize = () => {
      if (window.visualViewport) {
        const offset = window.innerHeight - window.visualViewport.height;
        setKeyboardOffset(offset > 0 ? offset : 0);

        // Se o teclado abrir, forçamos um scroll para o fim
        if (offset > 0) {
            setTimeout(scrollToBottom, 100);
        }
      }
    };

    window.visualViewport.addEventListener('resize', handleResize);
    return () => window.visualViewport?.removeEventListener('resize', handleResize);
  }, []);

  // FUNÇÃO DE AUTO-SCROLL
  const scrollToBottom = () => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior: 'smooth', 
            block: 'end' 
        });
    }
  };

  // Scroll sempre que as mensagens mudam ou o bot para de digitar
  useEffect(() => {
    if (isOpen) {
      scrollToBottom();
    }
  }, [messages, isOpen, isTyping]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);

    const docOptions: ChatOption[] = [
        { label: 'CPF (Pessoa Física)', value: 'CPF' },
        { label: 'CNPJ (Empresa)', value: 'CNPJ' }
    ];
    addBotMessage("Você gostaria de iniciar com CPF ou CNPJ?", 2500, () => setCurrentStep('DOC_TYPE'), docOptions);
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_TYPE':
        if (value === 'CPF' || value === 'CNPJ') {
            setUserData(prev => ({ ...prev, documentType: value }));
            addBotMessage(`Perfeito. Por favor, digite o número do ${value}.`, 600, () => setCurrentStep('DOC_VALUE'));
        } else {
            addBotMessage("Por favor, selecione uma das opções abaixo.", 500);
        }
        break;

      case 'DOC_VALUE':
        const isCpf = userData.documentType === 'CPF';
        const isValidDoc = isCpf ? validateCPF(value) : validateCNPJ(value);

        if (!isValidDoc) {
            addBotMessage(`${userData.documentType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        const formattedDoc = isCpf ? formatCPF(value) : formatCNPJ(value);
        setUserData(prev => ({ ...prev, documentValue: formattedDoc }));
        addBotMessage("Documento validado! ✅", 500);
        addBotMessage("Qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-4">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-50 flex flex-col items-end pointer-events-none"
      style={{ 
        bottom: `calc(${keyboardOffset}px + 1.5rem)`, 
        right: '1.5rem',
        left: keyboardOffset > 0 ? '1.5rem' : 'auto'
      }}
    >

      {/* Balão de Notificação */}
      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      {/* JANELA DO CHAT */}
      <div 
        className={`bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          keyboardOffset > 0 ? 'w-full h-[45vh]' : 'w-[320px] sm:w-[380px] h-[500px]'
        }`}
      >
         {/* Header */}
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         {/* Messages Area */}
         <div 
            ref={scrollContainerRef}
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            {/* O Ref de scroll deve ficar APÓS as opções para garantir que elas apareçam */}
            <div ref={messagesEndRef} className="h-2" />
         </div>

         {/* Input Area */}
         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      {/* FAB (Floating Action Button) */}
      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto ${
            isOpen ? 'bg-slate-700 rotate-90' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: keyboardOffset > 0 && isOpen ? 'none' : 'flex' }}
      >
        {isOpen ? (
            <IconX className="w-6 h-6 text-white" />
        ) : (
            <>
                <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
                <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
                {showNotification && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
                )}
            </>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

// CONFIGURAÇÃO DA URL DO N8N
const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_TYPE'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  const [keyboardOffset, setKeyboardOffset] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // FUNÇÃO DE AUTO-SCROLL REFORÇADA
  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior, 
            block: 'end' 
        });
    }
  };

  // Efeito para detectar teclado e ajustar viewport
  useEffect(() => {
    if (!window.visualViewport) return;

    const handleResize = () => {
      if (window.visualViewport) {
        const offset = window.innerHeight - window.visualViewport.height;
        setKeyboardOffset(offset > 0 ? offset : 0);

        if (offset > 0) {
            // Scroll imediato quando o teclado abre
            setTimeout(() => scrollToBottom('auto'), 50);
        }
      }
    };

    window.visualViewport.addEventListener('resize', handleResize);
    return () => window.visualViewport?.removeEventListener('resize', handleResize);
  }, []);

  // Scroll automático quando mensagens mudam, bot digita ou para de digitar
  useEffect(() => {
    if (isOpen) {
      // Pequeno delay para garantir que o DOM (especialmente os botões) já foi renderizado
      const timer = setTimeout(() => scrollToBottom(), 100);
      return () => clearTimeout(timer);
    }
  }, [messages, isOpen, isTyping, currentStep]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);

    const docOptions: ChatOption[] = [
        { label: 'CPF (Pessoa Física)', value: 'CPF' },
        { label: 'CNPJ (Empresa)', value: 'CNPJ' }
    ];
    addBotMessage("Você gostaria de iniciar com CPF ou CNPJ?", 2500, () => setCurrentStep('DOC_TYPE'), docOptions);
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_TYPE':
        if (value === 'CPF' || value === 'CNPJ') {
            setUserData(prev => ({ ...prev, documentType: value as any }));
            addBotMessage(`Perfeito. Por favor, digite o número do ${value}.`, 600, () => setCurrentStep('DOC_VALUE'));
        } else {
            addBotMessage("Por favor, selecione uma das opções abaixo.", 500);
        }
        break;

      case 'DOC_VALUE':
        const isCpf = userData.documentType === 'CPF';
        const isValidDoc = isCpf ? validateCPF(value) : validateCNPJ(value);

        if (!isValidDoc) {
            addBotMessage(`${userData.documentType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        const formattedDoc = isCpf ? formatCPF(value) : formatCNPJ(value);
        setUserData(prev => ({ ...prev, documentValue: formattedDoc }));
        addBotMessage("Documento validado! ✅", 500);
        addBotMessage("Qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-2">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-50 flex flex-col items-end pointer-events-none"
      style={{ 
        bottom: `calc(${keyboardOffset}px + 1.5rem)`, 
        right: '1.5rem',
        left: keyboardOffset > 0 ? '1.5rem' : 'auto'
      }}
    >

      {/* Balão de Notificação */}
      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      {/* JANELA DO CHAT */}
      <div 
        className={`bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          keyboardOffset > 0 ? 'w-full h-[45vh]' : 'w-[320px] sm:w-[380px] h-[500px]'
        }`}
      >
         {/* Header */}
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         {/* Messages Area */}
         <div 
            ref={scrollContainerRef}
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            {/* O Ref de scroll foi movido para envolver as opções e o final */}
            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} className="h-4 w-full clear-both" />
         </div>

         {/* Input Area */}
         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      {/* FAB (Floating Action Button) */}
      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto ${
            isOpen ? 'bg-slate-700 rotate-90' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: keyboardOffset > 0 && isOpen ? 'none' : 'flex' }}
      >
        {isOpen ? (
            <IconX className="w-6 h-6 text-white" />
        ) : (
            <>
                <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
                <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
                {showNotification && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
                )}
            </>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_TYPE'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  // Estado para controle refinado da viewport (teclado)
  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // FUNÇÃO DE AUTO-SCROLL
  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior, 
            block: 'end' 
        });
    }
  };

  // MONITORAMENTO DA VIEWPORT (TECLADO MOBILE)
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;

    const handleViewportChange = () => {
      const kHeight = window.innerHeight - vv.height;
      setKeyboardHeight(kHeight > 0 ? kHeight : 0);
      setViewportHeight(vv.height);

      if (kHeight > 0) {
        // Quando o teclado abre ou muda, garante que o final do chat esteja visível
        setTimeout(() => scrollToBottom('auto'), 100);
      }
    };

    vv.addEventListener('resize', handleViewportChange);
    vv.addEventListener('scroll', handleViewportChange);

    // Inicializar valores
    handleViewportChange();

    return () => {
      vv.removeEventListener('resize', handleViewportChange);
      vv.removeEventListener('scroll', handleViewportChange);
    };
  }, []);

  // Scroll sempre que mensagens mudam ou o bot para de digitar
  useEffect(() => {
    if (isOpen) {
      const timer = setTimeout(() => scrollToBottom(), 100);
      return () => clearTimeout(timer);
    }
  }, [messages, isOpen, isTyping]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  // Foco automático e scroll no input ao mudar de passo
  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
        scrollToBottom();
      }, 150);
      return () => clearTimeout(timer);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);

    const docOptions: ChatOption[] = [
        { label: 'CPF (Pessoa Física)', value: 'CPF' },
        { label: 'CNPJ (Empresa)', value: 'CNPJ' }
    ];
    addBotMessage("Você gostaria de iniciar com CPF ou CNPJ?", 2500, () => setCurrentStep('DOC_TYPE'), docOptions);
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_TYPE':
        if (value === 'CPF' || value === 'CNPJ') {
            setUserData(prev => ({ ...prev, documentType: value as any }));
            addBotMessage(`Perfeito. Por favor, digite o número do ${value}.`, 600, () => setCurrentStep('DOC_VALUE'));
        } else {
            addBotMessage("Por favor, selecione uma das opções abaixo.", 500);
        }
        break;

      case 'DOC_VALUE':
        const isCpf = userData.documentType === 'CPF';
        const isValidDoc = isCpf ? validateCPF(value) : validateCNPJ(value);

        if (!isValidDoc) {
            addBotMessage(`${userData.documentType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        const formattedDoc = isCpf ? formatCPF(value) : formatCNPJ(value);
        setUserData(prev => ({ ...prev, documentValue: formattedDoc }));
        addBotMessage("Documento validado! ✅", 500);
        addBotMessage("Qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-2">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-[9999] flex flex-col items-end pointer-events-none w-full sm:w-auto"
      style={{ 
        bottom: keyboardHeight > 0 ? `${keyboardHeight}px` : '1.5rem', 
        right: keyboardHeight > 0 ? '0' : '1.5rem',
        left: keyboardHeight > 0 ? '0' : 'auto',
        transition: 'bottom 0.1s ease-out'
      }}
    >

      {/* Balão de Notificação */}
      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 mr-6 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      {/* JANELA DO CHAT */}
      <div 
        className={`bg-slate-900 border-slate-700 shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          keyboardHeight > 0 
          ? 'w-full h-full max-h-[100dvh] rounded-none' 
          : 'w-[320px] sm:w-[380px] h-[500px] rounded-2xl border'
        }`}
        style={{ 
            height: keyboardHeight > 0 ? `${viewportHeight}px` : undefined 
        }}
      >
         {/* Header */}
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         {/* Messages Area */}
         <div 
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} className="h-4 w-full clear-both" />
         </div>

         {/* Input Area */}
         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  onFocus={() => setTimeout(scrollToBottom, 200)}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      {/* FAB (Floating Action Button) */}
      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto mr-6 mb-0 ${
            isOpen ? 'bg-slate-700 rotate-90 scale-0' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: isOpen ? 'none' : 'flex' }}
      >
        <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
        <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
        {showNotification && (
            <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior, 
            block: 'end' 
        });
    }
  };

  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;

    const handleViewportChange = () => {
      const kHeight = window.innerHeight - vv.height;
      setKeyboardHeight(kHeight > 0 ? kHeight : 0);
      setViewportHeight(vv.height);

      if (kHeight > 0) {
        setTimeout(() => scrollToBottom('auto'), 100);
      }
    };

    vv.addEventListener('resize', handleViewportChange);
    vv.addEventListener('scroll', handleViewportChange);
    handleViewportChange();

    return () => {
      vv.removeEventListener('resize', handleViewportChange);
      vv.removeEventListener('scroll', handleViewportChange);
    };
  }, []);

  useEffect(() => {
    if (isOpen) {
      const timer = setTimeout(() => scrollToBottom(), 100);
      return () => clearTimeout(timer);
    }
  }, [messages, isOpen, isTyping]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
        scrollToBottom();
      }, 150);
      return () => clearTimeout(timer);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);
    addBotMessage("Por favor, digite seu CPF ou o CNPJ da sua empresa.", 2500, () => setCurrentStep('DOC_VALUE'));
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_VALUE':
        const digitsOnly = value.replace(/\D/g, '');
        let docType: 'CPF' | 'CNPJ' | '' = '';
        let isValidDoc = false;
        let formattedDoc = '';

        if (digitsOnly.length === 11) {
          docType = 'CPF';
          isValidDoc = validateCPF(digitsOnly);
          formattedDoc = formatCPF(digitsOnly);
        } else if (digitsOnly.length === 14) {
          docType = 'CNPJ';
          isValidDoc = validateCNPJ(digitsOnly);
          formattedDoc = formatCNPJ(digitsOnly);
        } else {
          addBotMessage("Documento inválido. Digite 11 números para CPF ou 14 para CNPJ.", 500);
          return;
        }

        if (!isValidDoc) {
            addBotMessage(`${docType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        setUserData(prev => ({ ...prev, documentType: docType, documentValue: formattedDoc }));
        addBotMessage(`${docType} validado com sucesso! ✅`, 500);
        addBotMessage("Agora, qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-2">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-[9999] flex flex-col items-end pointer-events-none w-full sm:w-auto"
      style={{ 
        bottom: keyboardHeight > 0 ? `${keyboardHeight}px` : '1.5rem', 
        right: keyboardHeight > 0 ? '0' : '1.5rem',
        left: keyboardHeight > 0 ? '0' : 'auto',
        transition: 'bottom 0.1s ease-out'
      }}
    >

      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 mr-6 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      <div 
        className={`bg-slate-900 border-slate-700 shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          keyboardHeight > 0 
          ? 'w-full h-full max-h-[100dvh] rounded-none' 
          : 'w-[320px] sm:w-[380px] h-[500px] rounded-2xl border'
        }`}
        style={{ 
            height: keyboardHeight > 0 ? `${viewportHeight}px` : undefined 
        }}
      >
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         <div 
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} className="h-4 w-full clear-both" />
         </div>

         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  onFocus={() => setTimeout(scrollToBottom, 200)}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto mr-6 mb-0 ${
            isOpen ? 'bg-slate-700 rotate-90 scale-0' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: isOpen ? 'none' : 'flex' }}
      >
        <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
        <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
        {showNotification && (
            <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Sistema de Scroll Automático Reforçado
  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior, 
            block: 'end' 
        });
    }
  };

  // Monitoramento avançado da Viewport para dispositivos móveis
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;

    const handleViewportChange = () => {
      const kHeight = window.innerHeight - vv.height;
      setKeyboardHeight(kHeight > 0 ? kHeight : 0);
      setViewportHeight(vv.height);

      // Scroll imediato ao abrir teclado ou redimensionar
      if (isOpen) {
        setTimeout(() => scrollToBottom('auto'), 50);
      }
    };

    vv.addEventListener('resize', handleViewportChange);
    vv.addEventListener('scroll', handleViewportChange);
    handleViewportChange();

    return () => {
      vv.removeEventListener('resize', handleViewportChange);
      vv.removeEventListener('scroll', handleViewportChange);
    };
  }, [isOpen]);

  // Scroll automático em todas as mudanças de estado cruciais
  useEffect(() => {
    if (isOpen) {
      const timer = setTimeout(() => scrollToBottom(), 100);
      return () => clearTimeout(timer);
    }
  }, [messages, isTyping, currentStep, isOpen]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  // Foco e scroll ao mudar de passo
  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
        scrollToBottom();
      }, 150);
      return () => clearTimeout(timer);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);
    addBotMessage("Por favor, digite seu CPF ou o CNPJ da sua empresa.", 2500, () => setCurrentStep('DOC_VALUE'));
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_VALUE':
        const digitsOnly = value.replace(/\D/g, '');
        let docType: 'CPF' | 'CNPJ' | '' = '';
        let isValidDoc = false;
        let formattedDoc = '';

        if (digitsOnly.length === 11) {
          docType = 'CPF';
          isValidDoc = validateCPF(digitsOnly);
          formattedDoc = formatCPF(digitsOnly);
        } else if (digitsOnly.length === 14) {
          docType = 'CNPJ';
          isValidDoc = validateCNPJ(digitsOnly);
          formattedDoc = formatCNPJ(digitsOnly);
        } else {
          addBotMessage("Documento inválido. Digite 11 números para CPF ou 14 para CNPJ.", 500);
          return;
        }

        if (!isValidDoc) {
            addBotMessage(`${docType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        setUserData(prev => ({ ...prev, documentType: docType, documentValue: formattedDoc }));
        addBotMessage(`${docType} validado com sucesso! ✅`, 500);
        addBotMessage("Agora, qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-2">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  // Determinar se o chat deve ser full screen (Mobile + Teclado)
  const isMobile = typeof window !== 'undefined' && window.innerWidth < 640;
  const isFullScreen = isOpen && isMobile && keyboardHeight > 0;

  return (
    <div 
      className="fixed z-[9999] flex flex-col items-end pointer-events-none"
      style={{ 
        bottom: isFullScreen ? '0' : (keyboardHeight > 0 ? `${keyboardHeight}px` : '1.5rem'), 
        right: isFullScreen ? '0' : (keyboardHeight > 0 ? '0' : '1.5rem'),
        left: isFullScreen ? '0' : (keyboardHeight > 0 ? '0' : 'auto'),
        top: isFullScreen ? '0' : 'auto',
        width: isFullScreen ? '100%' : 'auto',
        transition: 'all 0.15s ease-out'
      }}
    >

      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 mr-6 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      <div 
        className={`bg-slate-900 border-slate-700 shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom pointer-events-auto ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        } ${
          isFullScreen 
          ? 'w-full h-full rounded-none border-none' 
          : 'w-[320px] sm:w-[380px] h-[500px] rounded-2xl border'
        }`}
        style={{ 
            height: isFullScreen ? `${viewportHeight}px` : (keyboardHeight > 0 ? `${viewportHeight}px` : undefined)
        }}
      >
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         <div 
            ref={scrollContainerRef}
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none shadow-lg' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} className="h-6 w-full clear-both" />
         </div>

         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  onFocus={() => {
                    // Scroll suave forçado ao focar
                    setTimeout(scrollToBottom, 300);
                  }}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2.5 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2.5 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-lg active:scale-95"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto mr-6 mb-0 ${
            isOpen ? 'bg-slate-700 rotate-90 scale-0' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: isOpen ? 'none' : 'flex' }}
      >
        <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
        <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
        {showNotification && (
            <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
        )}
      </button>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { IconMessageCircle, IconX, IconSend, IconShield } from './Icons';
import { ChatMessage, ChatOption, UserData } from '../types';
import { 
  validateCPF, 
  validateCNPJ, 
  validatePhone, 
  validateEmail, 
  formatCPF, 
  formatCNPJ, 
  formatPhone 
} from '../utils/validators';

const N8N_WEBHOOK_URL = 'https://n8nwebhook.shirabe.com.br/webhook/lpshigueme'; 

type ChatStep = 
  | 'INTRO'
  | 'DOC_VALUE'
  | 'NAME' 
  | 'COMPANY' 
  | 'EMAIL' 
  | 'PHONE' 
  | 'CITY'
  | 'REVENUE' 
  | 'REGIME' 
  | 'SECTOR' 
  | 'MAIN_NEED' 
  | 'MESSAGE' 
  | 'SUBMITTING' 
  | 'SUCCESS' 
  | 'ERROR';

export const AIAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [currentStep, setCurrentStep] = useState<ChatStep>('INTRO');
  const [userInput, setUserInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showNotification, setShowNotification] = useState(false);

  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(0);

  const [userData, setUserData] = useState<UserData>({
    documentType: '',
    documentValue: '',
    name: '', 
    email: '', 
    phone: '', 
    city: '',
    company: '', 
    revenue: '', 
    regime: '', 
    sector: '', 
    mainNeed: '', 
    message: ''
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Sistema de Scroll Automático Reforçado
  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ 
            behavior, 
            block: 'end' 
        });
    }
  };

  // Monitoramento da Viewport para ajuste de posição (sem Full Screen)
  useEffect(() => {
    const vv = window.visualViewport;
    if (!vv) return;

    const handleViewportChange = () => {
      const kHeight = window.innerHeight - vv.height;
      setKeyboardHeight(kHeight > 0 ? kHeight : 0);
      setViewportHeight(vv.height);

      if (isOpen) {
        setTimeout(() => scrollToBottom('auto'), 50);
      }
    };

    vv.addEventListener('resize', handleViewportChange);
    vv.addEventListener('scroll', handleViewportChange);
    handleViewportChange();

    return () => {
      vv.removeEventListener('resize', handleViewportChange);
      vv.removeEventListener('scroll', handleViewportChange);
    };
  }, [isOpen]);

  // Scroll automático para cada nova mensagem ou interação
  useEffect(() => {
    if (isOpen) {
      const timer = setTimeout(() => scrollToBottom(), 100);
      return () => clearTimeout(timer);
    }
  }, [messages, isTyping, currentStep, isOpen]);

  useEffect(() => {
    const handleOpenChat = () => {
      setIsOpen(true);
      setShowNotification(false);
      if (!hasOpened) {
          setHasOpened(true);
          startConversation();
      }
    };
    window.addEventListener('open-chat', handleOpenChat);
    return () => window.removeEventListener('open-chat', handleOpenChat);
  }, [hasOpened]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!isOpen && !hasOpened) {
        setShowNotification(true);
      }
    }, 3000);
    return () => clearTimeout(timer);
  }, [isOpen, hasOpened]);

  useEffect(() => {
    if (isOpen && !hasOpened) {
      setHasOpened(true);
      setShowNotification(false);
      startConversation();
    }
  }, [isOpen]);

  // Foco e scroll ao mudar de passo (pergunta)
  useEffect(() => {
    if (isOpen && !isTyping && currentStep !== 'INTRO' && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
        scrollToBottom();
      }, 150);
      return () => clearTimeout(timer);
    }
  }, [isTyping, currentStep, isOpen]);

  const startConversation = () => {
    setMessages([]);
    addBotMessage("Olá! Sou o seu assistente virtual. 🤖", 500);
    addBotMessage("Para iniciarmos o diagnóstico tributário, preciso identificar você.", 1500);
    addBotMessage("Por favor, digite seu CPF ou o CNPJ da sua empresa.", 2500, () => setCurrentStep('DOC_VALUE'));
  };

  const addBotMessage = (text: string, delay: number = 0, callback?: () => void, options?: ChatOption[]) => {
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'bot',
        content: text,
        type: options ? 'options' : 'text',
        options: options
      }]);
      if (callback) callback();
    }, delay);
  };

  const addUserMessage = (text: string) => {
    setMessages(prev => [...prev, {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      type: 'text'
    }]);
  };

  const handleOptionSelect = (option: ChatOption) => {
    addUserMessage(option.label);
    processInput(option.value);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userInput.trim()) return;

    addUserMessage(userInput);
    processInput(userInput);
    setUserInput('');
  };

  const processInput = (value: string) => {
    const cleanValue = value.trim();

    switch (currentStep) {
      case 'DOC_VALUE':
        const digitsOnly = value.replace(/\D/g, '');
        let docType: 'CPF' | 'CNPJ' | '' = '';
        let isValidDoc = false;
        let formattedDoc = '';

        if (digitsOnly.length === 11) {
          docType = 'CPF';
          isValidDoc = validateCPF(digitsOnly);
          formattedDoc = formatCPF(digitsOnly);
        } else if (digitsOnly.length === 14) {
          docType = 'CNPJ';
          isValidDoc = validateCNPJ(digitsOnly);
          formattedDoc = formatCNPJ(digitsOnly);
        } else {
          addBotMessage("Documento inválido. Digite 11 números para CPF ou 14 para CNPJ.", 500);
          return;
        }

        if (!isValidDoc) {
            addBotMessage(`${docType} inválido. Por favor, verifique os números e tente novamente.`, 500);
            return;
        }

        setUserData(prev => ({ ...prev, documentType: docType, documentValue: formattedDoc }));
        addBotMessage(`${docType} validado com sucesso! ✅`, 500);
        addBotMessage("Agora, qual é o seu nome completo?", 1500, () => setCurrentStep('NAME'));
        break;

      case 'NAME':
        if (cleanValue.length < 3 || cleanValue.split(' ').length < 2) {
            addBotMessage("Por favor, digite seu nome e sobrenome.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, name: cleanValue }));
        addBotMessage(`Prazer, ${cleanValue.split(' ')[0]}! Qual o nome da sua empresa?`, 600, () => setCurrentStep('COMPANY'));
        break;

      case 'COMPANY':
        setUserData(prev => ({ ...prev, company: cleanValue }));
        addBotMessage("Agora, qual é o seu melhor e-mail corporativo?", 600, () => setCurrentStep('EMAIL'));
        break;

      case 'EMAIL':
        const emailValidation = validateEmail(cleanValue);
        if (!emailValidation.isValid) {
            addBotMessage(emailValidation.message || "E-mail inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, email: cleanValue.toLowerCase() }));
        addBotMessage("Anotado. Qual seu WhatsApp (DDD + 9 dígitos)?", 600, () => setCurrentStep('PHONE'));
        break;

      case 'PHONE':
        const phoneValidation = validatePhone(cleanValue);
        if (!phoneValidation.isValid) {
            addBotMessage(phoneValidation.message || "Telefone inválido.", 500);
            return;
        }
        setUserData(prev => ({ ...prev, phone: formatPhone(cleanValue) }));
        addBotMessage("Qual a sua cidade e estado (ex: Maringá - PR)?", 600, () => setCurrentStep('CITY'));
        break;

      case 'CITY':
        if (cleanValue.length < 2) {
             addBotMessage("Por favor, digite o nome da cidade.", 500);
             return;
        }

        setUserData(prev => ({ ...prev, city: cleanValue }));
        addBotMessage(`Certo.`, 500);

        const revenueOptions: ChatOption[] = [
            { label: 'Até R$ 80k (MEI)', value: 'ate_50k' },
            { label: 'R$ 80k - R$ 300k', value: '50k_300k' },
            { label: 'R$ 300k - R$ 1M', value: '300k_1m' },
            { label: 'R$ 1M - R$ 5M', value: '1m_5m' },
            { label: 'Acima de R$ 5M', value: 'acima_5m' },
        ];
        addBotMessage("Qual o faturamento mensal estimado da empresa?", 1500, () => setCurrentStep('REVENUE'), revenueOptions);
        break;

      case 'REVENUE':
        setUserData(prev => ({ ...prev, revenue: value }));

        const regimeOptions: ChatOption[] = [
            { label: 'MEI', value: 'mei' },
            { label: 'Simples Nacional', value: 'simples' },
            { label: 'Lucro Presumido', value: 'presumido' },
            { label: 'Lucro Real', value: 'real' },
            { label: 'Não sei / Abertura', value: 'nao_sei' },
        ];
        addBotMessage("Qual o Regime Tributário atual?", 600, () => setCurrentStep('REGIME'), regimeOptions);
        break;

      case 'REGIME':
        setUserData(prev => ({ ...prev, regime: value }));

        const sectorOptions: ChatOption[] = [
            { label: 'Indústria', value: 'industria' },
            { label: 'Comércio/Varejo', value: 'comercio' },
            { label: 'Atacado', value: 'atacado'},
            { label: 'Serviços', value: 'servicos' },
            { label: 'Agro', value: 'agro' },
            { label: 'Saúde', value: 'saude' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual é o setor de atuação principal?", 600, () => setCurrentStep('SECTOR'), sectorOptions);
        break;

      case 'SECTOR':
        setUserData(prev => ({ ...prev, sector: value }));

        const needOptions: ChatOption[] = [
            { label: 'Reduzir Impostos', value: 'reduzir_carga' },
            { label: 'Resolver Dívidas', value: 'dividas' },
            { label: 'Recup. Créditos', value: 'recuperacao_credito' },
            { label: 'BPO Financeiro', value: 'bpo' },
            { label: 'Reforma Tributária', value: 'reforma_tributaria' },
            { label: 'Outro', value: 'outro' },
        ];
        addBotMessage("Qual seu maior desafio ou objetivo hoje?", 600, () => setCurrentStep('MAIN_NEED'), needOptions);
        break;

      case 'MAIN_NEED':
        setUserData(prev => ({ ...prev, mainNeed: value }));
        addBotMessage("Para finalizar, descreva brevemente como podemos ajudar.", 600, () => setCurrentStep('MESSAGE'));
        break;

      case 'MESSAGE':
        setUserData(prev => {
            const finalData = { ...prev, message: value };
            submitToN8N(finalData);
            return finalData;
        });
        setCurrentStep('SUBMITTING');
        break;

      default:
        break;
    }
  };

  const submitToN8N = async (data: UserData) => {
    addBotMessage("Analisando seus dados e enviando para nossa equipe...", 500);

    try {
        const response = await fetch(N8N_WEBHOOK_URL, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(data),
        });

        if (response.ok) {
            setCurrentStep('SUCCESS');
            addBotMessage("✅ Tudo certo! Recebemos sua solicitação.", 1000);
            addBotMessage("Nossos especialistas em inteligência tributária entrarão em contato em breve pelo WhatsApp.", 2000);
        } else {
            throw new Error(`Erro ${response.status}: ${response.statusText}`);
        }

    } catch (error) {
        console.error("Erro envio chat:", error);
        setCurrentStep('ERROR');
        addBotMessage("Ops! Houve um erro de conexão.", 1000);
        addBotMessage("Por favor, tente nos chamar diretamente no WhatsApp pelo botão no rodapé.", 2000);
    }
  };

  const renderOptions = () => {
    const lastMessage = messages[messages.length - 1];
    if (lastMessage?.role === 'bot' && lastMessage?.options && !isTyping && currentStep !== 'SUBMITTING' && currentStep !== 'SUCCESS') {
        return (
            <div className="flex flex-wrap gap-2 mt-2 px-1 pb-2">
                {lastMessage.options.map((opt) => (
                    <button
                        key={opt.value}
                        onClick={() => handleOptionSelect(opt)}
                        className="bg-blue-600 text-white text-xs py-1.5 px-3 rounded-lg hover:bg-blue-700 transition-colors shadow-sm active:scale-95"
                    >
                        {opt.label}
                    </button>
                ))}
            </div>
        );
    }
    return null;
  };

  const isInputDisabled = currentStep === 'INTRO' || currentStep === 'SUBMITTING' || currentStep === 'SUCCESS' || currentStep === 'ERROR' || isTyping || (messages[messages.length - 1]?.role === 'bot' && !!messages[messages.length - 1]?.options);

  return (
    <div 
      className="fixed z-[9999] flex flex-col items-end pointer-events-none"
      style={{ 
        // O chat se move para cima para não ser coberto pelo teclado, mas mantém margens
        bottom: keyboardHeight > 0 ? `${keyboardHeight + 10}px` : '1.5rem', 
        right: '1.5rem',
        left: '1.5rem', // No mobile, isso ajuda a centralizar se a largura for w-auto
        maxWidth: 'calc(100% - 3rem)',
        width: 'auto',
        transition: 'bottom 0.2s ease-out'
      }}
    >

      {!isOpen && (
        <div 
          className={`bg-white text-slate-800 px-4 py-3 rounded-2xl shadow-xl border border-slate-100 max-w-[250px] mb-3 transition-all duration-500 origin-bottom-right pointer-events-auto ${
            showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-75 translate-y-4 pointer-events-none'
          }`}
        >
          <div className="flex items-start gap-3">
             <div className="bg-blue-100 p-1.5 rounded-full shrink-0">
                <IconShield className="w-4 h-4 text-blue-600" />
             </div>
             <div>
                <p className="text-xs font-bold mb-1">Diagnóstico Gratuito</p>
                <p className="text-xs text-slate-500 leading-tight">
                  Posso analisar o perfil tributário da sua empresa agora?
                </p>
             </div>
             <button 
                onClick={(e) => { e.stopPropagation(); setShowNotification(false); }}
                className="text-slate-400 hover:text-slate-600"
             >
               <IconX className="w-3 h-3" />
             </button>
          </div>
        </div>
      )}

      <div 
        className={`bg-slate-900 border-slate-700 shadow-2xl flex flex-col overflow-hidden transition-all duration-300 origin-bottom pointer-events-auto w-full sm:w-[380px] h-[500px] rounded-2xl border ${
          isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none hidden'
        }`}
        style={{ 
            // Altura máxima ajustada para caber no viewport restante quando o teclado estiver aberto
            maxHeight: keyboardHeight > 0 ? `calc(${viewportHeight}px - 2rem)` : '500px'
        }}
      >
         <div className="bg-slate-950 p-4 flex items-center justify-between border-b border-slate-800 shrink-0">
            <div className="flex items-center gap-3">
               <div className="relative">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-600 to-blue-800 flex items-center justify-center border border-blue-400/30">
                     <IconShield className="w-5 h-5 text-white" />
                  </div>
                  <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 rounded-full border-2 border-slate-900"></div>
               </div>
               <div>
                  <h4 className="font-bold text-white text-sm">Assistente IA</h4>
                  <p className="text-[10px] text-blue-400">Shigueme Consultoria</p>
               </div>
            </div>
            <button 
               onClick={() => setIsOpen(false)}
               className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
            >
               <IconX className="w-5 h-5" />
            </button>
         </div>

         <div 
            ref={scrollContainerRef}
            className="flex-grow p-4 overflow-y-auto bg-slate-900 scrollbar-hide space-y-3"
         >
            {messages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[85%] text-xs md:text-sm p-3 rounded-2xl ${
                      msg.role === 'user' 
                      ? 'bg-blue-600 text-white rounded-br-none shadow-lg' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
                   }`}>
                      {msg.content}
                   </div>
                </div>
            ))}

            {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex gap-1">
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                      <span className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></span>
                   </div>
                </div>
            )}

            <div className="pl-2">
                {renderOptions()}
            </div>

            <div ref={messagesEndRef} className="h-6 w-full clear-both" />
         </div>

         <div className="p-3 bg-slate-950 border-t border-slate-800 shrink-0">
            <form onSubmit={handleTextSubmit} className="flex gap-2">
               <input
                  ref={inputRef}
                  onFocus={() => {
                    setTimeout(scrollToBottom, 300);
                  }}
                  type={currentStep === 'PHONE' || currentStep === 'DOC_VALUE' ? 'tel' : currentStep === 'EMAIL' ? 'email' : 'text'}
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder={isInputDisabled ? "Aguarde..." : "Digite aqui..."}
                  disabled={isInputDisabled}
                  className="flex-grow bg-slate-900 text-white text-sm rounded-lg px-3 py-2.5 outline-none border border-slate-800 focus:border-blue-500 transition-colors disabled:opacity-50"
                  autoComplete="off"
               />
               <button 
                  type="submit"
                  disabled={isInputDisabled || !userInput.trim()}
                  className="bg-blue-600 hover:bg-blue-500 text-white p-2.5 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-lg active:scale-95"
               >
                  <IconSend className="w-5 h-5" />
               </button>
            </form>
         </div>
      </div>

      <button
        onClick={() => {
            setIsOpen(!isOpen);
            setShowNotification(false);
        }}
        className={`group relative flex items-center justify-center w-14 h-14 sm:w-16 sm:h-16 rounded-full shadow-2xl transition-all duration-300 z-50 pointer-events-auto mb-0 ${
            isOpen ? 'bg-slate-700 rotate-90 scale-0' : 'bg-blue-600 hover:bg-blue-500 hover:scale-110'
        }`}
        aria-label="Abrir Chat"
        style={{ display: isOpen ? 'none' : 'flex' }}
      >
        <span className="absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-20 animate-[ping_2s_cubic-bezier(0,0,0.2,1)_infinite]"></span>
        <IconMessageCircle className="w-7 h-7 text-white relative z-10" />
        {showNotification && (
            <span className="absolute top-0 right-0 w-4 h-4 bg-red-500 border-2 border-white rounded-full"></span>
        )}
      </button>
    </div>
  );
};

